// Tests of the php backend (packages/fsm-compiler/src/backends/php.mjs, docs/spec/fsm.md, B-4 and B-6): the files of the
// order example are the golden files under tests/golden/php, byte for byte, in the order the backend returns them, and the test
// module is the golden tests/golden/php/Vectors.php. The golden files were written by the generator once, after a review of its
// output against B-6 (docs/plans/fsm-v1.md, C-5). Every generated file is also checked by the php linter, and the namespace
// that the command line passes is refused when it is not a PHP namespace.
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';
import { files, vectorsFile } from '../src/backends/php.mjs';
import { normalize } from '../src/core/normalize.mjs';
import { vectors } from '../src/core/vectors.mjs';
import { jsonStore } from '../src/store-json/store.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '../../..');
const GOLDEN = path.join(HERE, 'golden/php');
const NAMESPACE = 'Polyspec\\FsmTest';
const NAMES = ['Order/State.php', 'Order/Event.php', 'Order/Step.php', 'Order/functions.php', 'Fsm/Code.php', 'Fsm/Error.php'];
const HEADER = /^<\?php\n\/\/ Code generated by fsm-gen from [^\n]+; DO NOT EDIT\.\n/;

/** The IRs and the lock of the repository's definitions (the order example). */
async function orderIrs() {
  const { definitions, lock, findings } = await jsonStore(ROOT).load();
  assert.deepEqual(findings, []);
  return { irs: definitions.map(normalize), lock };
}

/** The files of the order example for the namespace NAMESPACE. */
async function orderFiles() {
  const { irs, lock } = await orderIrs();
  return files(irs, lock, { phpNamespace: NAMESPACE });
}

test('the files of the order example are the golden files, byte for byte, in the backend order', async () => {
  const out = await orderFiles();
  assert.deepEqual(out.map(file => file.path), NAMES);
  for (const file of out) {
    assert.equal(file.content, readFileSync(path.join(GOLDEN, 'src', file.path), 'utf8'), `${file.path} differs from its golden file`);
  }
});

test('every generated file starts with <?php and the fsm-gen header of its machine or of fsm, and ends with one line break', async () => {
  for (const file of await orderFiles()) {
    assert.match(file.content, HEADER, file.path);
    const from = file.path.startsWith('Order/') ? 'order' : 'fsm';
    assert.equal(file.content.split('\n')[1], `// Code generated by fsm-gen from ${from}; DO NOT EDIT.`, file.path);
    assert.ok(file.content.endsWith('\n') && !file.content.endsWith('\n\n'), `${file.path} must end with exactly one line break`);
  }
});

test('the test module of the order example is the golden Vectors.php, byte for byte', async () => {
  const { irs, lock } = await orderIrs();
  const generated = irs.map(ir => vectors(ir, lock));
  assert.equal(vectorsFile(generated, { phpNamespace: NAMESPACE }), readFileSync(path.join(GOLDEN, 'Vectors.php'), 'utf8'));
});

test('the backend is deterministic: the same input gives the same files', async () => {
  const { irs, lock } = await orderIrs();
  assert.deepEqual(files(irs, lock, { phpNamespace: NAMESPACE }), files(irs, lock, { phpNamespace: NAMESPACE }));
});

test('the namespace is required and must be a PHP namespace of letters, digits and single backslashes', async () => {
  const { irs, lock } = await orderIrs();
  for (const phpNamespace of [undefined, '', 'Bad Name', '\\Polyspec', 'Polyspec\\', 'Polyspec\\\\FsmTest', '1Fsm', 'Poly-spec']) {
    assert.throws(() => files(irs, lock, { phpNamespace }), /php namespace/, JSON.stringify(phpNamespace));
    assert.throws(() => vectorsFile([], { phpNamespace }), /php namespace/, JSON.stringify(phpNamespace));
  }
});

test('every generated php file passes the php linter (php -l)', async (t) => {
  const dir = mkdtempSync(path.join(tmpdir(), 'fsm-php-backend-'));
  t.after(() => rmSync(dir, { recursive: true, force: true }));
  const { irs, lock } = await orderIrs();
  const testModule = { path: 'Tests/Vectors.php', content: vectorsFile(irs.map(ir => vectors(ir, lock)), { phpNamespace: NAMESPACE }) };
  for (const file of [...await orderFiles(), testModule]) {
    const target = path.join(dir, file.path);
    mkdirSync(path.dirname(target), { recursive: true });
    writeFileSync(target, file.content);
    const lint = spawnSync('php', ['-l', target], { encoding: 'utf8' });
    assert.equal(lint.status, 0, `${file.path}: ${lint.stdout}${lint.stderr}`);
  }
});
